            title = "The Mapmaker's Lunchbox",
            tagline = "A lunchbox full of sketches helps a class map accessible routes around town.",
            parts = listOf(
                StoryPart(1, "A Folded Map", listOf("Sade found a folded street map inside a donated lunchbox at the school lost-property archive. The map showed pencil marks and small notes beside public buildings.", "The teacher explained that the lunchbox had belonged to a former student who enjoyed drawing routes.", "The class decided to find out whether the sketches could become a useful community map.")),
                StoryPart(2, "The First Route", listOf("The mapmaker's notes described a route between the school, library, clinic, and bus stop.", "Some streets had changed, so the class knew the old map could not be treated as current guidance.", "They asked the local council for public maps and accessibility information.")),
                StoryPart(3, "A Walk with Permission", listOf("The teacher arranged a supervised route review with the council's community liaison officer.", "Students noted crossings, public pavements, signs, and places where information was unclear.", "They avoided entering private property and recorded only public, relevant details.")),
                StoryPart(4, "A Missing Crossing", listOf("The old map showed a pedestrian crossing that had been moved. The class checked the current road markings and official notice.", "They updated the draft and marked the old location as historical rather than directing anyone there.", "The officer thanked them for checking before publishing.")),
                StoryPart(5, "Listening to Users", listOf("The class invited residents to review the draft, including people who used mobility aids and families with young children.", "They asked what information would make a route easier to understand, without assuming everyone's needs were the same.", "Suggestions included clearer labels, resting places, and notes about steep sections.")),
                StoryPart(6, "The Lunchbox Owner", listOf("The school located the former student, now an urban design technician. She was pleased to see the sketches and explained that they were practice drawings.", "She offered to review the map for clarity but reminded the students that official route changes must come from the responsible authority.", "The class credited her original inspiration and kept the current information separate.")),
                StoryPart(7, "A Better Legend", listOf("Students redesigned the map legend with clear symbols and a plain-language key.", "They added a date and a note directing readers to official sources for changing conditions.", "The teacher checked that the map remained readable in print and on a phone.")),
                StoryPart(8, "The Review Meeting", listOf("The council liaison officer reviewed the draft and corrected two public facility names.", "Residents checked the route descriptions and suggested one additional public resting area.", "The class made the changes and recorded who had verified each section.")),
                StoryPart(9, "Sharing the Map", listOf("The school library displayed the map with a short explanation of its limits and update date.", "The council shared the official version through its community information channel after completing its own review.", "The former student visited and donated the original sketches to the school archive.")),
                StoryPart(10, "Routes That Keep Learning", listOf("The class created a process for checking the map each term and sending corrections to the council.", "The lunchbox and original drawings were stored safely, while the approved map remained available to residents.", "Sade realised that a useful map was never simply a drawing. It was a promise to check, listen, update, and make public information easier to understand."))
